// Citation formatting (src/cite.js + the vendored citeproc-js and CSL
// styles), checked against the style guides' own published examples.
//
// Requirement (2026-10-29): citations generated by script, with correct
// formatting. Each expected string below is the guide's example, so a
// wrong style file, engine, locale or field mapping shows up as a diff.

const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { loadInVM } = require("./harness");

const V = path.join(__dirname, "..", "..", "src", "vendor", "citeproc");
const files = {};
for (const f of fs.readdirSync(path.join(V, "styles"))) files["styles/" + f] = fs.readFileSync(path.join(V, "styles", f), "utf8");
for (const f of fs.readdirSync(path.join(V, "locales"))) files["locales/" + f] = fs.readFileSync(path.join(V, "locales", f), "utf8");

const sb = loadInVM(["vendor/citeproc/citeproc.js", "cite.js"], { module: undefined, console });
const Cite = sb.Cite;
const fmt = (items, style) => Cite.format(items, style, "text", files);

// APA Publication Manual (7th ed.), §10.1 example 1.
const GRADY = { id: "grady", type: "article-journal",
  title: "Emotions in storybooks: A comparison of storybooks that represent ethnic and racial groups in the United States",
  "container-title": "Psychology of Popular Media Culture", volume: "8", issue: "3", page: "207-217",
  DOI: "10.1037/ppm0000185", issued: { "date-parts": [[2019]] },
  author: [["Grady", "Jessica Stoltzfus"], ["Her", "Malina"], ["Moreno", "Geena"], ["Perez", "Catherine"], ["Yelinek", "Jillian"]]
    .map(([family, given]) => ({ family, given })) };

// MLA Handbook (9th ed.), journal article example.
const GOLDMAN = { id: "goldman", type: "article-journal",
  title: "Questions of Transport: Reading Primo Levi Reading Dante", "container-title": "The Georgia Review",
  volume: "64", issue: "1", page: "69-88", issued: { "date-parts": [[2010]] },
  author: [{ family: "Goldman", given: "Anne" }] };

test("APA 7 matches the Publication Manual's example", async () => {
  // Catches a wrong style file, the en-US locale missing, or a mapping
  // that drops the issue, the DOI or the '&' before the last author.
  const r = await fmt([GRADY], "apa");
  assert.equal(r.rows[0].reference,
    "Grady, J. S., Her, M., Moreno, G., Perez, C., & Yelinek, J. (2019). Emotions in storybooks: " +
    "A comparison of storybooks that represent ethnic and racial groups in the United States. " +
    "Psychology of Popular Media Culture, 8(3), 207–217. https://doi.org/10.1037/ppm0000185");
  assert.equal(r.rows[0].intext, "(Grady et al., 2019)");
});

test("MLA 9 prints full names, title case and punctuation inside the quotes", async () => {
  // Catches the citeproc-py faults that ruled it out: initials for MLA's
  // full given names, and the period left outside the closing quote.
  const r = await fmt([GOLDMAN], "mla");
  assert.equal(r.rows[0].reference,
    "Goldman, Anne. “Questions of Transport: Reading Primo Levi Reading Dante.” " +
    "The Georgia Review, vol. 64, no. 1, 2010, pp. 69–88.");
  assert.equal(r.rows[0].intext, "(Goldman)");
});

test("Chicago author-date: full names, 'and', year after the authors", async () => {
  // Catches Chicago being given APA-like initials or the year in parentheses.
  const r = await fmt([GRADY], "chicago");
  assert.match(r.rows[0].reference,
    /^Grady, Jessica Stoltzfus, Malina Her, Geena Moreno, Catherine Perez, and Jillian Yelinek\. 2019\. “Emotions in Storybooks: .*States\.” Psychology of Popular Media Culture 8 \(3\): 207–17\. https:\/\/doi\.org\/10\.1037\/ppm0000185\.$/);
  assert.equal(r.rows[0].intext, "(Grady et al. 2019)");
});

test("Harvard (Cite Them Right) is British: single quotes, comma outside", async () => {
  // Catches the style running under the US locale (double quotes,
  // punctuation inside), since the style file names no language.
  const r = await fmt([GRADY], "harvard");
  assert.match(r.rows[0].reference, /‘Emotions in storybooks: .*United States’, Psychology/);
});

test("numbered styles number the list and cite by number", async () => {
  // Catches Vancouver / IEEE losing their numbers or the space after them.
  const v = await fmt([GRADY], "vancouver");
  assert.match(v.bibliography[0], /^1\. Grady JS, Her M, Moreno G, Perez C, Yelinek J\. Emotions in storybooks/);
  const i = await fmt([GRADY], "ieee");
  assert.match(i.bibliography[0], /^\[1\] J\. S\. Grady, M\. Her, G\. Moreno, C\. Perez, and J\. Yelinek, “Emotions in storybooks: .*States,” /);
  assert.equal(i.rows[0].intext, "[1]");
});

test("sentence-case styles use the sentence-case title; the others do not", async () => {
  // Catches APA printing a stored Title Case title, or MLA being handed
  // the lower-cased one (MLA wants title case).
  const item = { ...GOLDMAN, id: "t", title: "Prospect Theory: An Analysis of Decision under Risk",
                 "title-sentence": "Prospect theory: An analysis of decision under risk" };
  const apa = await fmt([item], "apa");
  assert.match(apa.rows[0].reference, /\(2010\)\. Prospect theory: An analysis of decision under risk\./);
  const mla = await fmt([item], "mla");
  assert.match(mla.rows[0].reference, /“Prospect Theory: An Analysis of Decision under Risk\.”/);
});

test("a list keeps the style's order and every item's own reference", async () => {
  // Catches references attached to the wrong paper when the style sorts
  // the list (APA by author) differently from the input order.
  const r = await fmt([GRADY, GOLDMAN], "apa");
  assert.match(r.bibliography[0], /^Goldman/);
  assert.match(r.rows.find(x => x.id === "grady").reference, /^Grady/);
  assert.match(r.rows.find(x => x.id === "goldman").reference, /^Goldman/);
});

test("copy-as-text removes markup and entities", () => {
  // Catches "<i>" or "&#38;" reaching a pasted reference.
  assert.equal(Cite.toPlain("Smith, A. &#38; Jones, B. <i>Journal</i>, 8"), "Smith, A. & Jones, B. Journal, 8");
});


test("the narrative form names the authors in the sentence", async () => {
  // Catches the in-a-sentence citation repeating the authors inside the
  // brackets, or MLA printing empty brackets after the name.
  assert.equal((await fmt([GRADY], "apa")).rows[0].narrative, "Grady et al. (2019)");
  assert.equal((await fmt([GRADY], "chicago")).rows[0].narrative, "Grady et al. (2019)");
  assert.equal((await fmt([GOLDMAN], "mla")).rows[0].narrative, "Goldman");
});
